      "domain": "capital_intelligence",
      "objective": "understand how public capital markets value the target company's business model, technology, and sector",
      "inputs_required": [
        "company_name"
      ],
      "process": [
        {
          "step": "company_characterization",
          "description": "understand core attributes of the company",
          "outputs": [
            "business_model",
            "technology",
            "industry"
          ],
          "requirements": [
            "business model must be clearly classified (e.g. marketplace, SaaS, B2B)",
            "technology must include name, description, and general how it works",
            "industry classification must be specific"
          ]
        },
        {
          "step": "comparable_selection",
          "description": "identify ~10 public comparable companies",
          "outputs": [
            "list_of_comparables"
          ],
          "requirements": [
            "companies should be in similar region OR relevant market",
            "must have exposure to similar technology",
            "include mix of companies (not just leaders)",
            "prioritize variation across sub-niches"
          ],
          "key_factors": [
            "geography",
            "technology",
            "sub_niche"
          ],
          "target_count": 10
        },
        {
          "step": "financial_data_collection",
          "description": "retrieve financial metrics from public sources",
          "source": "Yahoo Finance",
          "outputs": [
            "PE_ratio",
            "EV_to_Revenue",
            "revenue_growth_rate",
            "historical_trends"
          ],
          "requirements": [
            "PE ratio is primary metric",
            "include EV/Revenue multiple",
            "include revenue growth rate when available",
            "track trends over time for each company"
          ]
        },
        {
          "step": "valuation_interpretation",
          "description": "analyze how the public market values the sector",
          "outputs": [
            "valuation_trend",
            "market_signal"
          ],
          "interpretation_rules": [
            "increasing multiples indicate rising market confidence",
            "stable multiples indicate steady perception",
            "declining multiples indicate weakening sentiment"
          ]
        }
      ],
      "success_criteria": [
        "company characterized across business model, technology, and industry",
        "approximately 10 relevant comparable companies identified",
        "financial metrics collected for most comparables",
        "valuation trends identified across companies",
        "clear interpretation of market sentiment"
      ],
      "failure_conditions": [
        "company not properly characterized",
        "fewer than 5 comparables identified",
        "insufficient financial data collected",
        "no clear valuation trend identified",
        "analysis lacks interpretation"
      ],
      "decision_rules": {
        "valid_comparable_if": [
          "same core product function",
          "same customer type (B2B vs B2C)",
          "similar value capture mechanism",
          "overlapping use case"
        ],
        "invalid_if": [
          "only tangential overlap (e.g. both use AI)",
          "different monetization model",
          "platform vs tool mismatch"
        ]
      },
      "comparables_constraints": [
        "must share core product function (not just same broad category)",
        "exclude large tech companies unless directly comparable at product level",
        "exclude marketplaces unless business model matches target",
        "avoid superficial AI-based matching"
      ],
      "grounding_enforcement": [
        "every numerical value must be traceable to a source",
        "every company comparison must match technology and business model",
        "do not infer product features unless explicitly extracted",
        "if data is missing, mark as unknown instead of filling"
      ],
      "decision_gate": {
        "investment_recommendation_allowed_only_if": [
          "at least 70% financial data coverage across comparables",
          "clear company characterization confirmed from source",
          "technology differentiation supported by evidence"
        ],
        "otherwise": "return conditional or incomplete assessment"
      },
      "common_failures": [
        "using large tech companies as lazy comparables",
        "confusing feature overlap with product overlap",
        "inferring product capabilities without evidence",
        "overgeneralizing from single source",
        "forcing conclusions without sufficient data"
      ]
    },
    {
      "domain": "technology_intelligence",
      "objective": "assess how novel and competitive the target company's technology is",
      "inputs_required": [
        "technology_description"
      ],
      "process": [
        {
          "step": "patent_search",
          "description": "map the technology space using patent data",
          "source": "Google Patents",
          "actions": [
            "search by technology type",
            "identify relevant patents",
            "collect filing dates and frequency"
          ],
          "outputs": [
            "patent_list",
            "patent_frequency",
            "patent_recency"
          ]
        },
        {
          "step": "chronological_mapping",
          "description": "understand evolution of the technology",
          "outputs": [
            "technology_timeline"
          ],
          "requirements": [
            "order patents chronologically",
            "identify progression of ideas and improvements",
            "highlight major shifts or breakthroughs"
          ]
        },
        {
          "step": "novelty_assessment",
          "description": "evaluate how crowded or unique the space is",
          "outputs": [
            "novelty_level",
            "competition_density",
            "risk_signal"
          ],
          "interpretation_rules": [
            "high patent volume indicates crowded space and lower entry angle",
            "low patent volume indicates niche or early-stage technology",
            "recent surge in patents indicates emerging trend",
            "lack of recent patents may indicate stagnation"
          ]
        }
      ],
      "success_criteria": [
        "relevant patents identified",
        "technology evolution mapped over time",
        "clear novelty assessment made",
        "competition density evaluated",
        "risk signal derived from patent landscape"
      ],
      "failure_conditions": [
        "no relevant patents found",
        "unable to determine patent trends",
        "no clear novelty conclusion",
        "analysis lacks interpretation"
      ],
      "technology_evaluation_axes": [
        "core capability (what it actually does)",
        "mechanism (how it works)",
        "dependency (models, infrastructure, data)",
        "defensibility (difficulty to replicate)",
        "position in stack (infrastructure vs tool vs application layer)"
      ],
      "grounding_enforcement": [
        "do not infer technical capabilities without explicit evidence",
        "separate claimed functionality from verified functionality",
        "avoid generic AI descriptions without mechanism-level detail"
      ],
      "common_failures": [
        "treating all AI systems as equivalent",
        "focusing on surface-level features instead of underlying mechanism",
        "assuming novelty without patent or technical evidence",
        "overgeneralizing from known big tech capabilities"
      ],
      "decision_gate": {
        "novelty_assessment_allowed_only_if": [
          "patent landscape or equivalent evidence analyzed",
          "technology mechanism understood at a high level",
          "clear comparison against existing approaches"
        ],
        "otherwise": "return partial assessment with unknowns"
      }
    }
  ]
}

